    const invoices = await http().get('/billing/invoices').query({ payerId: 'person-9' }).expect(200);
    expect(invoices.body).toEqual([
      expect.objectContaining({ source: { type: 'NO_SHOW', id: appointmentId }, totalCents: 10_000 }),
    ]);
  });

